import{_ as n,C as s,o as l,c as h,j as e,a as o,E as r,a3 as i}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Knives","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/knives.md","filePath":"uk/tools/knives.md"}'),d={name:"uk/tools/knives.md"};function c(u,a,p,g,m,b){const t=s("Screenshot");return l(),h("div",null,[a[0]||(a[0]=e("h1",{id:"knives",tabindex:"-1"},[o("Knives "),e("a",{class:"header-anchor",href:"#knives","aria-label":'Permalink to "Knives"'},"​")],-1)),a[1]||(a[1]=e("p",null,"Knives — сканер руху цін. Він стежить за кожним тікером на кожній увімкненій біржі й показує картку в момент, коли котрийсь із них рухається сильніше за встановлений вами поріг — вгору або вниз.",-1)),a[2]||(a[2]=e("p",null,[o("Усі його показники рахуються за "),e("strong",null,"поточною 5-хвилинною свічкою"),o(". Тікер з'являється тому, що зрушила "),e("em",null,"ця"),o(" свічка, а не через 24-годинну цифру.")],-1)),r(t,{src:"knives",alt:"Вікно Knives з картками тікерів і міні-графіками",caption:"Вікно Knives"}),a[3]||(a[3]=i('<h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><h3 id="поки-нічого-не-спрацювало" tabindex="-1">Поки нічого не спрацювало <a class="header-anchor" href="#поки-нічого-не-спрацювало" aria-label="Permalink to &quot;Поки нічого не спрацювало&quot;">​</a></h3><p>Коли жоден поріг ще не перетнуто, вікно показує стан очікування замість карток:</p><ul><li><strong>Listening</strong> — пульсуючий напис, а за ним по одному запису на кожну увімкнену біржу: її іконка, відсоток спрацювання і поріг обсягу, якщо для неї увімкнено фільтр обсягу. Це живе зведення того, що Knives зараз готовий зловити.</li><li><strong>No exchanges armed</strong> — усі біржі вимкнені. Спрацювати не може ніщо. Увімкніть щонайменше одну в панелі налаштувань.</li></ul><h3 id="картка-тікера" tabindex="-1">Картка тікера <a class="header-anchor" href="#картка-тікера" aria-label="Permalink to &quot;Картка тікера&quot;">​</a></h3><p>Кожна картка складається з рядка-заголовка й міні-графіка під ним.</p><p>У заголовку, зліва направо:</p><ul><li><strong>Іконки бірж</strong> — на яких біржах торгується тікер. При наведенні показує <code>Listed on &lt;біржа&gt;</code>. Їх можна повністю приховати — див. <a href="#іконки-бірж">Show icons</a>.</li><li><strong>Значок NEW</strong> — тікер було залістовано протягом останніх 60 секунд. Значок забарвлений у колір біржі, яка його залістувала, а наведення показує, якої саме. Зникає, щойно тікеру більше за хвилину.</li><li><strong>Символ тікера</strong> — клацніть, щоб скопіювати його в буфер обміну. На мить з&#39;явиться <code>Copied!</code> для підтвердження.</li></ul><p>Праворуч:</p><ul><li><strong>Обсяг</strong> — обсяг поточної 5хв свічки в доларах. Показується лише коли увімкнено відображення обсягу — див. <a href="#show-volume-in-tickers">Show volume</a>.</li><li><strong>Зміна ціни</strong> — відсоткова зміна поточної 5хв свічки, зі знаком.</li><li><strong>Кнопка розгортання</strong> — відкриває тікер на весь екран.</li></ul><h3 id="що-означають-кольори" tabindex="-1">Що означають кольори <a class="header-anchor" href="#що-означають-кольори" aria-label="Permalink to &quot;Що означають кольори&quot;">​</a></h3><p>Картка забарвлює свій відсоток <em>і</em> смужку заголовка в зелений або червоний, щойно рух поточної свічки досягає порогу <strong>% Change</strong> тієї біржі. Нижче порогу показник лишається нейтральним.</p><p>Тобто колір означає не «ціна зросла», а «цей рух досяг рівня, про який ви просили повідомити». Картка може бути на екрані й показувати нейтральний результат, якщо ціна вже відкотилася нижче порогу.</p><div class="warning custom-block"><p class="custom-block-title">Напрям визначається окремо для кожної біржі</p><p>Для забарвлення береться поріг тієї біржі, з якої прийшла картка. Якщо ви задали різні значення <strong>% Change</strong> для різних бірж, дві картки з однаковим відсотком можуть бути забарвлені по-різному.</p></div><h3 id="повнии-екран" tabindex="-1">Повний екран <a class="header-anchor" href="#повнии-екран" aria-label="Permalink to &quot;Повний екран&quot;">​</a></h3><p>Кнопка розгортання відкриває один тікер на все вікно з більшим графіком і перемикачем таймфреймів: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code> і <code>1w</code>.</p><p>У випадному списку таймфрейми можна позначати зірочкою, щоб закріпити їх рядком швидкого доступу поруч із перемикачем. Обрані таймфрейми спільні з повноекранними графіками інших інструментів.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Knives</strong> у головному вікні.</p>',19)),r(t,{src:"knives-settings",alt:"Налаштування відображення, пріоритету даних і іконок бірж у Knives",caption:"Налаштування Knives — відображення, пріоритет, іконки"}),a[4]||(a[4]=i('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-tickers" tabindex="-1">Max tickers <a class="header-anchor" href="#max-tickers" aria-label="Permalink to &quot;Max tickers&quot;">​</a></h4><p>Скільки карток тікерів вікно показує одночасно. Діапазон <strong>від 3 до 66</strong>, за замовчуванням 12.</p><h4 id="show-volume-in-tickers" tabindex="-1">Show volume in tickers <a class="header-anchor" href="#show-volume-in-tickers" aria-label="Permalink to &quot;Show volume in tickers&quot;">​</a></h4><p>Показує значення обсягу в заголовку кожної картки.</p><p>Цей перемикач <strong>примусово увімкнено й заблоковано</strong>, коли фільтр обсягу увімкнено хоча б для однієї біржі: якщо ви фільтруєте за обсягом, Knives завжди показує той обсяг, за яким фільтрував. Опис при цьому змінюється на <code>Always on when volume filter is enabled</code>. Щоб повернути керування перемикачем, вимкніть фільтр обсягу на всіх біржах.</p><h3 id="chart-data-priority" tabindex="-1">Chart data priority <a class="header-anchor" href="#chart-data-priority" aria-label="Permalink to &quot;Chart data priority&quot;">​</a></h3><h4 id="exchange-priority" tabindex="-1">Exchange priority <a class="header-anchor" href="#exchange-priority" aria-label="Permalink to &quot;Exchange priority&quot;">​</a></h4><p>Список усіх п&#39;яти бірж із перетягуванням. Тягніть запис мишею вгору або вниз, щоб змінити його ранг.</p><p>Це визначає, <strong>яка біржа постачає свічки для міні-графіка</strong>, коли тікер торгується більш ніж на одній. Перемагає перша в списку біржа, яка увімкнена і має цей тікер.</p><p>На те, які біржі можуть спричинити сповіщення, це не впливає — за це відповідає перемикач <strong>Enable</strong> для кожної біржі нижче.</p><h3 id="іконки-бірж" tabindex="-1">Іконки бірж <a class="header-anchor" href="#іконки-бірж" aria-label="Permalink to &quot;Іконки бірж&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Показує або приховує іконки бірж на всіх картках тікерів. Вимкнено — картка щільніша й простіша; увімкнено — одразу видно, де торгується тікер.</p><h3 id="налаштування-для-кожноі-біржі" tabindex="-1">Налаштування для кожної біржі <a class="header-anchor" href="#налаштування-для-кожноі-біржі" aria-label="Permalink to &quot;Налаштування для кожної біржі&quot;">​</a></h3><p>Knives має однаковий блок налаштувань для кожної з бірж: <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate.io</strong>, <strong>OKX</strong> і <strong>Hyperliquid</strong>. Кожна налаштовується незалежно — пороги, фільтри обсягу та увімкнення окремі для кожної.</p><h4 id="enable-біржа" tabindex="-1">Enable &lt;біржа&gt; <a class="header-anchor" href="#enable-біржа" aria-label="Permalink to &quot;Enable \\&lt;біржа\\&gt;&quot;">​</a></h4><p>Чи отримує Knives сповіщення з цієї біржі взагалі. Вимкнено — біржа не сканується, і її тікери не можуть створювати картки. Усі п&#39;ять за замовчуванням увімкнені.</p><p>Вимкнення біржі робить решту блока неактивною.</p><h4 id="change" tabindex="-1">% Change <a class="header-anchor" href="#change" aria-label="Permalink to &quot;% Change&quot;">​</a></h4><p>Рух на поточній 5хв свічці, який спричиняє сповіщення для цієї біржі. Діапазон <strong>від 2% до 10%</strong> з кроком 0.5%, за замовчуванням 2%.</p><p>Це основний поріг. Він також визначає, коли показник картки стає зеленим або червоним.</p><h4 id="high-threshold" tabindex="-1">High threshold <a class="header-anchor" href="#high-threshold" aria-label="Permalink to &quot;High threshold&quot;">​</a></h4><p>Рівень, що вважається значним рухом для цієї біржі, і точка, на якій спрацьовує <a href="#price-change-sound">звук зміни ціни</a>. Діапазон <strong>від 2% до 10%</strong> з кроком 0.5%, за замовчуванням 6%.</p><div class="warning custom-block"><p class="custom-block-title">Цей повзунок додається до % Change</p><p>Значення поруч із повзунком — це <strong>% Change + High threshold</strong>, а не власне значення повзунка: при % Change 2% і повзунку на 6% напис показує <strong>8.0%</strong>, і саме там спрацьовує звук.</p><p>Читайте напис, а не положення повзунка.</p></div><p>Оскільки значення додається, підвищення <strong>% Change</strong> підіймає і рівень значного руху. Спершу задайте базовий поріг, а тоді налаштовуйте цей поверх нього.</p><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фільтрує тікери цієї біржі за обсягом торгів, щоб рухи з низькою ліквідністю до вас не доходили. За замовчуванням вимкнено.</p><p>Увімкнення для будь-якої біржі також примусово вмикає <a href="#show-volume-in-tickers">Show volume in tickers</a>.</p><h4 id="volume-threshold" tabindex="-1">Volume threshold <a class="header-anchor" href="#volume-threshold" aria-label="Permalink to &quot;Volume threshold&quot;">​</a></h4><p>Мінімальний обсяг у доларах на поточній 5хв свічці, потрібний тікеру, щоб він міг створити картку. Діапазон <strong>від $100K до $10M</strong> з кроком $100K, за замовчуванням $1M.</p><p>Неактивний, поки для цієї біржі не увімкнено фільтр обсягу.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-ticker-sound" tabindex="-1">New ticker sound <a class="header-anchor" href="#new-ticker-sound" aria-label="Permalink to &quot;New ticker sound&quot;">​</a></h4><p>Відтворює звук, коли у вікні з&#39;являється новий тікер.</p><h4 id="price-change-sound" tabindex="-1">Price change sound <a class="header-anchor" href="#price-change-sound" aria-label="Permalink to &quot;Price change sound&quot;">​</a></h4><p>Відтворює звук, коли рух досягає рівня значного руху для цієї біржі — числа, яке показано поруч із повзунком <a href="#high-threshold">High threshold</a>.</p><p>Спрацьовує щонайбільше раз на тікер за свічку, тож тікер, який продовжує рухатися в межах тієї самої 5хв свічки, не дзвонитиме багаторазово.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Обидва звуки глобальні для Knives, а не окремі для кожної біржі, незалежні один від одного, і кожен обмежений одним відтворенням на 2 секунди.</p></div><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/alerts.html">Alerts</a> — відхилення цін між біржами замість рухів на одній</li><li><a href="/manual/uk/tools/monitor.html">Monitor</a> — ранжований огляд усього ринку замість стрічки спрацювань</li><li><a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a> — кольори свічок, які використовують міні-графіки</li><li><a href="/manual/uk/customize/majors.html">Шар мажорів</a> — доступний на повноекранному графіку</li></ul>',41))])}const q=n(d,[["render",c]]);export{f as __pageData,q as default};
